"""Helpers for reporting installed distribution versions."""

from __future__ import annotations

from importlib import metadata


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Return installed versions for the given distribution names.

    Each input name is preserved exactly as given in the returned mapping.
    Matching against installed distributions is case-insensitive.
    """
    installed = {dist.metadata["Name"].casefold(): dist.version for dist in metadata.distributions() if dist.metadata.get("Name")}

    report: dict[str, str | None] = {}
    for name in names:
        report[name] = installed.get(name.casefold())
    return report
